  2	
  3	// The one way JusPrin reports an unexpected error (AGENTS.md, Error
  4	// handling): a failure no person decided an outcome for travels up unchanged
  5	// to the handler at the top of its entry point, and that handler, and only
  6	// it, calls report_unexpected_error. The person is told "Something went wrong
  7	// on our side" in ErrorReportDialog and nothing more specific; the report
  8	// goes straight to the app's Sentry project (SentryClient.hpp) once they
  9	// press "Report to JusPrin team" or after they turned automatic reports on.
 10	//
 11	// The top handlers today: the Agent and Home pages' message handlers
 12	// (AgentWebView, HomeWebView), the pumps that read an AI reply or title and a
 13	// key check (AgentHost::pump_stream, AgentHost::pump_setup, reporting through
 14	// the handler AgentWebView gives them), every place JusPrin's own code starts
 15	// running by itself -- a CallAfter, a timer, an HTTP callback, a thread --
 16	// through reported() below, and the pages' own top level, which sends a
 17	// report_error message with its Sentry event (WebShared/errorReports.ts). A
 18	// tool call's failure goes to the AI model instead; one in the app's own work
 19	// is also sent through report_if_automatic, when automatic reports are on.
 20	// An exception that leaves any other native event is OrcaSlicer's to handle,
 21	// exactly as upstream handles it (GUI_App::OnExceptionInMainLoop).
 22	
 23	#include <string>
 24	#include <vector>
 25	#include <utility>
 26	
 27	namespace Slic3r::GUI::JusPrin {
 28	
 29	// What a report holds: the lines "See what the report contains" lists. The
 30	// event Sentry receives adds what Sentry's SDKs collect (SentryEvent.hpp):
 31	// the stack, the loaded modules, the machine, the recent steps.
 32	struct ErrorReport
 33	{
 34	    std::string app;   // "JusPrin 2.0.0 (OrcaSlicer 2.5.0)"
 35	    std::string os;    // "macOS 26.3"
 36	    std::string doing; // what the app was doing, said by the top handler
 37	    std::string error; // the error as it reached the top, unchanged
 38	    std::string where; // the stack, where one exists (the pages' for now)
 39	    // A page's own Sentry event, as JSON, when a page reported; empty for
 40	    // the app's own.
 41	    std::string page_event;
 42	    // Where the app found its own failure (ThrowStack.hpp failure_stack()),
 43	    // innermost first; empty when it was not taken.
 44	    std::vector<void*> stack;
 45	};
 46	
 47	// The AppConfig key of "report errors automatically", off until the person
 48	// turns it on in the dialog or in Preferences › Updates.
 49	inline constexpr const char* kReportErrorsKey = "jusprin_report_errors_automatically";
 50	
 51	// Reports one unexpected error: sends it at once when automatic reports are
 52	// on, otherwise opens the dialog after the current event, over the window in
 53	// front. Only top handlers call this.
 54	void report_unexpected_error(std::string doing, std::string error, std::string where = {}, std::string page_event = {});
 55	
 56	// Reports a tool call that failed in the app's own work, whose error already
 57	// went to the AI model, or a start report the server answered with a fault
 58	// (LaunchReport): sent only when automatic reports are on, and no dialog
 59	// opens. Any thread.
 60	void report_if_automatic(std::string doing, std::string error);
 61	
 62	// The exception being handled, as a report names it: its type and what().
 63	// Call inside a catch block.
 64	std::string describe_current_exception();
 65	
 66	// The top handler of an entry point JusPrin's own code starts: wraps the
 67	// body of a CallAfter, a timer, an HTTP callback or a thread, so that an
 68	// exception leaving it is reported, saying the app was `doing` this. Any
 69	// thread.
 70	template<class Body> auto reported(const char* doing, Body body)
 71	{
 72	    return [doing, body = std::move(body)](auto&&... arguments) mutable {
 73	        try {
 74	            body(std::forward<decltype(arguments)>(arguments)...);
 75	        } catch (...) {
 76	            report_unexpected_error(doing, describe_current_exception());
 77	        }
 78	    };
 79	}
 80	
 81	// The report as it would be sent now, for the dialog.
 82	ErrorReport make_error_report(std::string doing, std::string error, std::string where, std::string page_event = {});
 83	
 84	} // namespace Slic3r::GUI::JusPrin
