 13	#include <wx/thread.h>
 14	#include <wx/utils.h>
 15	#include <wx/window.h>
 16	
 17	#include <algorithm>
 18	#include <deque>
 19	#include <filesystem>
 20	#include <typeinfo>
 21	#include <utility>
 22	#include <vector>
 23	
 24	namespace Slic3r::GUI::JusPrin {
 25	
 26	namespace {
 27	
 28	std::string os_label()
 29	{
 30	    int major = 0, minor = 0, micro = 0;
 31	    wxGetOsVersion(&major, &minor, &micro);
 32	#if defined(__APPLE__)
 33	    const std::string name = "macOS";
 34	#elif defined(_WIN32)
 35	    const std::string name = "Windows";
 36	#else
 37	    const std::string name = "Linux";
 38	#endif
 39	    return name + " " + std::to_string(major) + "." + std::to_string(minor) + (micro > 0 ? "." + std::to_string(micro) : "");
 40	}
 41	
 42	bool reports_automatically()
 43	{
 44	    return wxGetApp().app_config != nullptr && wxGetApp().app_config->get_bool(kReportErrorsKey);
 45	}
 46	
 47	// The reports waiting for the person, one dialog at a time. A failure that
 48	// repeats while its dialog is open or waiting adds nothing: the person has one
 49	// thing to answer. Nor does one they already answered in this run: a failure
 50	// that comes back each time a window is in front again would otherwise reopen
 51	// the dialog as soon as it closes, since closing it puts the window in front.
 52	std::deque<ErrorReport>  g_waiting;
 53	std::vector<ErrorReport> g_answered;
 54	bool                     g_showing = false;
 55	
 56	bool same_failure(const ErrorReport& a, const ErrorReport& b) { return a.doing == b.doing && a.error == b.error; }
 57	
 58	void show_next()
 59	{
 60	    if (g_showing || g_waiting.empty())
 61	        return;
 62	    g_showing = true;
 63	    const ErrorReport report = g_waiting.front();
 64	    const ErrorReportDialog::Answer answer = ErrorReportDialog::ask(report);
 65	    g_waiting.pop_front();
 66	    g_answered.push_back(report);
 67	    g_showing = false;
 68	    if (answer.automatically) {
 69	        wxGetApp().app_config->set_bool(kReportErrorsKey, true);
 70	        wxGetApp().app_config->save();
 71	        sentry_follow_setting(true);
 72	    }
 73	    if (answer.report)
 74	        sentry_send(report, answer.automatically);
 75	    // Once reports go automatically, the ones still waiting go too.
 76	    if (answer.automatically) {
 77	        for (const ErrorReport& waiting : g_waiting)
 78	            sentry_send(waiting, true);
 79	        g_waiting.clear();
 80	    }
 81	    if (!g_waiting.empty())
 82	        wxGetApp().CallAfter([] { show_next(); });
 83	}
 84	
 85	} // namespace
 86	
 87	ErrorReport make_error_report(std::string doing, std::string error, std::string where, std::string page_event)
 88	{
 89	    return ErrorReport{Updates::version_label(), os_label(), std::move(doing), std::move(error), std::move(where), std::move(page_event)};
 90	}
 91	
 92	namespace {
 93	
 94	void report_unexpected(std::string doing, std::string error, std::string where, std::string page_event, std::vector<void*> stack)
 95	{
 96	    // An entry point on another thread (an HTTP callback, a worker) reports
 97	    // on the main thread, where the waiting reports and the dialog live.
 98	    if (!wxThread::IsMain()) {
 99	        wxGetApp().CallAfter([doing = std::move(doing), error = std::move(error), where = std::move(where), page_event = std::move(page_event),
100	                              stack = std::move(stack)]() mutable {
101	            report_unexpected(std::move(doing), std::move(error), std::move(where), std::move(page_event), std::move(stack));
102	        });
103	        return;
104	    }
105	    ErrorReport report = make_error_report(std::move(doing), std::move(error), std::move(where), std::move(page_event));
106	    report.stack = std::move(stack);
107	    BOOST_LOG_TRIVIAL(error) << "Unexpected error while " << report.doing << ": " << report.error;
108	    if (reports_automatically()) {
109	        sentry_send(report, true);
110	        return;
111	    }
112	    const auto same = [&report](const ErrorReport& asked) { return same_failure(asked, report); };
113	    if (std::any_of(g_waiting.begin(), g_waiting.end(), same) || std::any_of(g_answered.begin(), g_answered.end(), same))
114	        return;
115	    g_waiting.push_back(std::move(report));
116	    // After the event that failed: the dialog's own loop never runs inside a
117	    // page's message handler or the main loop's exception hook.
118	    wxGetApp().CallAfter([] { show_next(); });
119	}
120	
121	void report_if_automatic(std::string doing, std::string error, std::vector<void*> stack)
122	{
123	    // From another thread (an HTTP callback), on the main thread, where the
124	    // settings it reads are written.
125	    if (!wxThread::IsMain()) {
126	        wxGetApp().CallAfter([doing = std::move(doing), error = std::move(error), stack = std::move(stack)]() mutable {
127	            report_if_automatic(std::move(doing), std::move(error), std::move(stack));
128	        });
129	        return;
130	    }
131	    if (reports_automatically()) {
132	        ErrorReport report = make_error_report(std::move(doing), std::move(error), {});
133	        report.stack = std::move(stack);
134	        sentry_send(report, true);
135	    }
136	}
137	
138	} // namespace
139	
140	// Both take the failure's stack here, in the code that reports it.
141	void report_unexpected_error(std::string doing, std::string error, std::string where, std::string page_event)
142	{
143	    report_unexpected(std::move(doing), std::move(error), std::move(where), std::move(page_event), failure_stack());
144	}
145	
146	void report_if_automatic(std::string doing, std::string error)
147	{
148	    report_if_automatic(std::move(doing), std::move(error), failure_stack());
149	}
150	
151	std::string describe_current_exception()
152	{
153	    try {
154	        throw;
155	    } catch (const std::filesystem::filesystem_error& error) {
156	        // Its paths name the person's files and projects, which a report
157	        // never holds: each becomes "<path>". Where a path is not found as
158	        // written (another encoding), only the error's code is kept.
159	        std::string text = error.what();
160	        for (const std::filesystem::path* path : {&error.path1(), &error.path2()}) {
161	            const std::string named = path->u8string();
162	            if (named.empty())
163	                continue;
164	            if (text.find(named) == std::string::npos) {
165	                text = error.code().message();
166	                break;
167	            }
168	            for (std::size_t at = text.find(named); at != std::string::npos; at = text.find(named, at + 6))
169	                text.replace(at, named.size(), "<path>");
170	        }
171	        return boost::core::demangle(typeid(error).name()) + ": " + text;
172	    } catch (const std::exception& error) {
173	        return boost::core::demangle(typeid(error).name()) + ": " + error.what();
174	    } catch (...) {
175	        return "an exception that is not a std::exception";
176	    }
177	}
178	
179	} // namespace Slic3r::GUI::JusPrin

