 46	// The SDK hands each envelope to OrcaSlicer's own HTTP client, which knows
 47	// the system's certificates and proxy on every platform; the SDK's own curl
 48	// transport would need both set up a second time. Anonymous: no token or
 49	// cookie goes with it.
 50	struct Uploads
 51	{
 52	    SentryDsn               dsn;
 53	    std::mutex              mutex;
 54	    std::condition_variable idle;
 55	    int                     pending = 0;
 56	};
 57	
 58	void upload_done(Uploads& uploads)
 59	{
 60	    std::lock_guard<std::mutex> lock(uploads.mutex);
 61	    --uploads.pending;
 62	    uploads.idle.notify_all();
 63	}
 64	
 65	void send_envelope(sentry_envelope_t* envelope, void* state)
 66	{
 67	    Uploads&    uploads = *static_cast<Uploads*>(state);
 68	    std::size_t size    = 0;
 69	    char*       body    = sentry_envelope_serialize(envelope, &size);
 70	    sentry_envelope_free(envelope);
 71	    std::string payload(body, size);
 72	    sentry_free(body);
 73	    {
 74	        std::lock_guard<std::mutex> lock(uploads.mutex);
 75	        ++uploads.pending;
 76	    }
 77	    Slic3r::Http::post(uploads.dsn.envelope_url)
 78	        .header("User-Agent", Updates::user_agent())
 79	        .header("Content-Type", "application/x-sentry-envelope")
 80	        .header("X-Sentry-Auth", sentry_auth_header(uploads.dsn, std::string("jusprin.app/") + Updates::kVersion))
 81	        .set_post_body(payload)
 82	        .tls_verify(true)
 83	        .timeout_connect(10)
 84	        .timeout_max(30)
 85	        .on_complete([&uploads](std::string, unsigned) { upload_done(uploads); })
 86	        .on_error([&uploads](std::string body, std::string error, unsigned status) {
 87	            BOOST_LOG_TRIVIAL(error) << "JusPrin could not send an error report to " << uploads.dsn.envelope_url << " (" << status
 88	                                     << "): " << error << " " << body;
 89	            upload_done(uploads);
 90	        })
 91	        .perform();
 92	}
 93	
 94	// Waits for the uploads under way, at most `timeout` milliseconds; 0 when
 95	// none is left.
 96	int wait_for_uploads(uint64_t timeout, void* state)
 97	{
 98	    Uploads&                     uploads = *static_cast<Uploads*>(state);
 99	    std::unique_lock<std::mutex> lock(uploads.mutex);
100	    return uploads.idle.wait_for(lock, std::chrono::milliseconds(timeout), [&uploads] { return uploads.pending == 0; }) ? 0 : 1;
101	}
