121	void start_sentry(const std::string& data_dir, bool reports_automatically)
122	{
123	    if (g_started)
124	        return;
125	    const std::optional<SentryDsn> dsn = parse_sentry_dsn(sentry_dsn());
126	    if (!dsn) {
127	        BOOST_LOG_TRIVIAL(warning) << "JusPrin sends no error reports or crashes: this build has no Sentry project to send them to";
128	        return;
129	    }
130	    // Lives as long as the app: the SDK may send until the process ends.
131	    auto* uploads = new Uploads{*dsn};
132	    sentry_transport_t* transport = sentry_transport_new(send_envelope);
133	    sentry_transport_set_state(transport, uploads);
134	    sentry_transport_set_flush_func(transport, wait_for_uploads);
135	    sentry_transport_set_shutdown_func(transport, wait_for_uploads);
136	
137	    // crashpad_handler ships beside the app's executable
138	    // (JusPrin/CMakeLists.txt).
139	    const std::filesystem::path handler = std::filesystem::path(boost::dll::program_location().native()).parent_path() /
140	#ifdef _WIN32
141	                                          "crashpad_handler.exe";
142	#else
143	                                          "crashpad_handler";
144	#endif
145	    const std::filesystem::path database = std::filesystem::u8path(data_dir) / "jusprin-sentry";
146	
147	    sentry_options_t* options = sentry_options_new();
148	    sentry_options_set_dsn(options, sentry_dsn().c_str());
149	    sentry_options_set_release(options, Updates::version_label().c_str());
150	    sentry_options_set_transport(options, transport);
151	    sentry_options_set_require_user_consent(options, 1);
152	#ifdef _WIN32
153	    sentry_options_set_handler_pathw(options, handler.wstring().c_str());
154	    sentry_options_set_database_pathw(options, database.wstring().c_str());
155	#else
156	    sentry_options_set_handler_path(options, handler.string().c_str());
157	    sentry_options_set_database_path(options, database.string().c_str());
158	#endif
159	    // Every report and crash carries this run's log.
160	    if (const std::optional<std::filesystem::path> log = log_file(data_dir)) {
161	#ifdef _WIN32
162	        sentry_options_add_attachmentw(options, log->wstring().c_str());
163	#else
164	        sentry_options_add_attachment(options, log->string().c_str());
165	#endif
166	    }
167	    if (sentry_init(options) != 0) {
168	        BOOST_LOG_TRIVIAL(error) << "JusPrin could not start Sentry's SDK; it sends no error reports or crashes";
169	        return;
170	    }
171	    g_started = true;
172	    start_recording_throws();
173	    sentry_follow_setting(reports_automatically);
174	    // Sends what is still under way when the app quits.
175	    std::atexit([] { sentry_close(); });
176	}
