188	void sentry_send(const ErrorReport& report, bool reports_automatically)
189	{
190	    if (!g_started) {
191	        BOOST_LOG_TRIVIAL(error) << "JusPrin could not send an error report: Sentry's SDK is not running";
192	        return;
193	    }
194	    sentry_value_t event = sentry_event(report);
195	    // Where the app found the failure: where it was thrown, or the code that
196	    // reported it; a page's event has the page's own stack.
197	    if (report.page_event.empty()) {
198	        std::vector<void*> frames = report.stack;
199	        sentry_event_value_add_stacktrace(event, frames.empty() ? nullptr : frames.data(), frames.size());
200	    }
201	    if (reports_automatically) {
202	        sentry_capture_event(event);
203	        return;
204	    }
205	    // The SDK decides when it captures, so consent given now covers this
206	    // event only.
207	    sentry_user_consent_give();
208	    sentry_capture_event(event);
209	    sentry_user_consent_revoke();
210	}
