 24	constexpr int kFrames = 64;
 25	
 26	struct Throw
 27	{
 28	    const void*                 object = nullptr; // the thrown object, which names the throw
 29	    int                         depth  = 0;
 30	    std::array<void*, kFrames>  frames{};
 31	#ifndef _WIN32
 32	    // The exception itself, once the app's own code has caught it. Holding it
 33	    // keeps its memory, so no other exception gets its address while this
 34	    // record names it.
 35	    std::exception_ptr          held;
 36	#endif
 37	};
 38	
 39	#ifndef _WIN32
 40	
 41	// The latest throws of every thread: an exception can be thrown on one and
 42	// reported on another (std::exception_ptr). A record names its exception
 43	// only while it holds it: the C++ runtime gives a freed exception's memory to
 44	// the next one, which may be thrown where no throw is recorded (inside
 45	// libc++.dylib on macOS). Never destroyed, so no held exception is destroyed
 46	// as the app exits.
 47	constexpr std::size_t kKept = 32;
 48	struct Throws
 49	{
 50	    std::mutex               mutex;
 51	    std::array<Throw, kKept> kept;
 52	    std::size_t              next = 0;
 53	};
 54	Throws& throws()
 55	{
 56	    static Throws* const all = new Throws();
 57	    return *all;
 58	}
 59	
 60	// The object `current` holds: libc++'s and libstdc++'s exception_ptr is the
 61	// thrown object's address.
 62	const void* object_of(const std::exception_ptr& current)
 63	{
 64	    static_assert(sizeof(std::exception_ptr) == sizeof(void*));
 65	    const void* object = nullptr;
 66	    std::memcpy(&object, &current, sizeof object);
 67	    return object;
 68	}
 69	
 70	// The newest record of `object`, or none.
 71	Throw* newest_of(Throws& all, const void* object)
 72	{
 73	    for (std::size_t back = 1; back <= kKept && back <= all.next; ++back) {
 74	        Throw& seen = all.kept[(all.next - back) % kKept];
 75	        if (seen.object == object)
 76	            return &seen;
 77	    }
 78	    return nullptr;
 79	}
 80	
 81	// Never inlined, so the stack always starts with this function's frame and
 82	// __cxa_throw's, which it leaves out: the first kept is the throwing function.
 83	constexpr int kOwnFrames = 2;
 84	__attribute__((noinline)) void record(const void* object)
 85	{
 86	    Throw throw_here;
 87	    throw_here.object = object;
 88	    std::array<void*, kFrames + kOwnFrames> frames{};
 89	    const int depth = backtrace(frames.data(), static_cast<int>(frames.size()));
 90	    for (int i = kOwnFrames; i < depth; ++i)
 91	        throw_here.frames[static_cast<std::size_t>(i - kOwnFrames)] = frames[static_cast<std::size_t>(i)];
 92	    throw_here.depth = depth > kOwnFrames ? depth - kOwnFrames : 0;
 93	    // Let go of the oldest record's exception after unlocking: destroying it
 94	    // runs its destructor.
 95	    std::exception_ptr oldest;
 96	    Throws&            all = throws();
 97	    std::lock_guard<std::mutex> lock(all.mutex);
 98	    Throw& slot = all.kept[all.next++ % kKept];
 99	    oldest      = std::move(slot.held);
100	    slot        = std::move(throw_here);
101	}
102	
103	// Called as the app's own code catches an exception: the newest record of its
104	// address takes hold of it, the first time. One case still names the wrong
105	// throw: a recorded exception that only code outside the app caught and freed,
106	// then one thrown where nothing is recorded, at the same address, caught by
107	// the app.
108	void hold_caught()
109	{
110	    std::exception_ptr current = std::current_exception();
111	    if (!current)
112	        return;
113	    Throws&                     all = throws();
114	    std::lock_guard<std::mutex> lock(all.mutex);
115	    Throw* seen = newest_of(all, object_of(current));
116	    if (seen != nullptr && !seen->held)
117	        seen->held = std::move(current);
118	}
119	
120	#else
121	
122	// The C++ runtime's record of the exception being handled on this thread
123	// (vcruntime; Boost.Stacktrace reads it the same way).
124	extern "C" void** __cdecl __current_exception();
125	
126	constexpr DWORD kCppException = 0xE06D7363;
127	
128	// The thrown object of the C++ exception being handled on this thread, which
129	// names its throw; none outside a catch block.
130	const void* current_object()
131	{
132	    const auto* record = static_cast<const EXCEPTION_RECORD*>(*__current_exception());
133	    if (record == nullptr || record->ExceptionCode != kCppException || record->NumberParameters < 3)
134	        return nullptr;
135	    return reinterpret_cast<const void*>(record->ExceptionInformation[1]);
136	}
137	
138	// Per thread: the handler runs on the throwing thread, and it sees every
139	// throw, the C++ library's too.
140	constexpr std::size_t kKept = 32;
141	struct Throws
142	{
143	    std::array<Throw, kKept> kept;
144	    std::size_t              next = 0;
145	};
146	thread_local Throws t_throws;
147	
148	LONG CALLBACK on_exception(EXCEPTION_POINTERS* info)
149	{
150	    const EXCEPTION_RECORD* record = info->ExceptionRecord;
151	    if (record->ExceptionCode != kCppException || record->NumberParameters < 3)
152	        return EXCEPTION_CONTINUE_SEARCH;
153	    const void* object = reinterpret_cast<const void*>(record->ExceptionInformation[1]);
154	    // A bare `throw;` passes no object, and one that throws the exception
155	    // being handled again names it: neither is a throw of its own.
156	    if (object == nullptr || object == current_object())
157	        return EXCEPTION_CONTINUE_SEARCH;
158	    Throw& slot = t_throws.kept[t_throws.next++ % kKept];
159	    slot.object = object;
160	    slot.depth  = CaptureStackBackTrace(0, kFrames, slot.frames.data(), nullptr);
161	    return EXCEPTION_CONTINUE_SEARCH;
162	}
163	
164	#endif
