172	std::vector<void*> current_exception_throw_stack()
173	{
174	    const std::exception_ptr current = std::current_exception();
175	    if (!current)
176	        return {};
177	    Throws&                     all = throws();
178	    std::lock_guard<std::mutex> lock(all.mutex);
179	    const Throw* seen = newest_of(all, object_of(current));
180	    if (seen == nullptr || seen->held != current)
181	        return {};
182	    return {seen->frames.begin(), seen->frames.begin() + seen->depth};
183	}
184	
185	__attribute__((noinline)) std::vector<void*> failure_stack()
186	{
187	    std::vector<void*> stack = current_exception_throw_stack();
188	    if (!stack.empty())
189	        return stack;
190	    // Leaves out this function's own frame: the first is its caller.
191	    std::array<void*, kFrames + 1> frames{};
192	    const int depth = backtrace(frames.data(), static_cast<int>(frames.size()));
193	    return depth > 1 ? std::vector<void*>(frames.begin() + 1, frames.begin() + depth) : std::vector<void*>{};
