204	std::vector<void*> current_exception_throw_stack()
205	{
206	    const void* object = current_object();
207	    if (object == nullptr)
208	        return {};
209	    for (std::size_t back = 1; back <= kKept && back <= t_throws.next; ++back) {
210	        const Throw& seen = t_throws.kept[(t_throws.next - back) % kKept];
211	        if (seen.object == object)
212	            return {seen.frames.begin(), seen.frames.begin() + seen.depth};
213	    }
214	    return {};
215	}
