217	__declspec(noinline) std::vector<void*> failure_stack()
218	{
219	    std::vector<void*> stack = current_exception_throw_stack();
220	    if (!stack.empty())
221	        return stack;
222	    // Leaves out this function's own frame: the first is its caller.
223	    std::array<void*, kFrames> frames{};
224	    const USHORT depth = CaptureStackBackTrace(1, kFrames, frames.data(), nullptr);
225	    return {frames.begin(), frames.begin() + depth};
226	}
