234	// The thrown type's parameter as the compiler already declares it: GCC
235	// declares __cxa_throw itself, with void*, once it has compiled any throw,
236	// and refuses a definition that differs; clang has it from <cxxabi.h>.
237	#if defined(__GNUC__) && !defined(__clang__)
238	using ThrownType = void;
239	#else
240	using ThrownType = std::type_info;
241	#endif
242	
243	// Every C++ throw in the app's own code and static libraries comes here
244	// first (ThrowStack.hpp), then goes on to the C++ library's own.
245	extern "C" void __cxa_throw(void* object, ThrownType* type, void (*destructor)(void*))
246	{
247	    using Real       = void (*)(void*, ThrownType*, void (*)(void*));
248	    static Real real = reinterpret_cast<Real>(dlsym(RTLD_NEXT, "__cxa_throw"));
249	    Slic3r::GUI::JusPrin::record(object);
250	    real(object, type, destructor);
251	    __builtin_unreachable();
252	}
253	
254	// Every catch in the app's own code and static libraries comes here (see
255	// hold_caught).
256	extern "C" void* __cxa_begin_catch(void* exception) noexcept
257	{
258	    using Real       = void* (*) (void*);
259	    static Real real = reinterpret_cast<Real>(dlsym(RTLD_NEXT, "__cxa_begin_catch"));
260	    void* const caught = real(exception);
261	    Slic3r::GUI::JusPrin::hold_caught();
262	    return caught;
263	}
264	
