12	std::optional<std::filesystem::path> page_file(const std::filesystem::path& root, const std::string& path)
13	{
14	    if (path.size() < 2 || path.front() != '/')
15	        return std::nullopt;
16	    std::filesystem::path file = root;
17	    std::string::size_type start = 1;
18	    while (start <= path.size()) {
19	        const std::string::size_type end  = std::min(path.find('/', start), path.size());
20	        const std::string            part = path.substr(start, end - start);
21	        if (part.empty() || part == "." || part == ".." || part.find('\\') != std::string::npos)
22	            return std::nullopt;
23	        file /= std::filesystem::u8path(part);
24	        start = end + 1;
25	    }
26	    std::error_code error;
27	    if (!std::filesystem::is_regular_file(file, error))
28	        return std::nullopt;
29	    return file;
30	}
31	
32	std::string page_file_type(const std::filesystem::path& file)
33	{
34	    std::string extension = file.extension().u8string();
35	    std::transform(extension.begin(), extension.end(), extension.begin(),
36	                   [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
37	    if (extension == ".html")
38	        return "text/html";
39	    if (extension == ".js" || extension == ".mjs")
40	        return "text/javascript";
41	    if (extension == ".css")
42	        return "text/css";
43	    if (extension == ".svg")
44	        return "image/svg+xml";
45	    if (extension == ".json")
46	        return "application/json";
47	    return {};
48	}
