     1	// The top of a page's own code (AGENTS.md, Error handling): Sentry's browser
     2	// SDK catches what nothing else did -- an uncaught error, a rejected promise --
     3	// and builds its event with the stack, the recent steps and the page's
     4	// context. The event is not sent from here: it goes to the app as a
     5	// report_error message, and the app asks the person, or not when automatic
     6	// reports are on, and sends it with its own Sentry SDK (Support/SentryClient).
     7	// The page holds no Sentry project and never reaches the network for this.
     8	import {
     9	  SDK_VERSION,
    10	  createTransport,
    11	  init,
    12	  rewriteFramesIntegration,
    13	  type ErrorEvent,
    14	  type EventHint,
    15	} from '@sentry/browser';
    16	
    17	// What a page sends the app: the two lines the report dialog shows, and the
    18	// event Sentry receives.
    19	export interface PageErrorReport {
    20	  error: string;
    21	  where: string;
    22	  event: ErrorEvent;
    23	}
    24	
    25	// Which build of the page this is: the commit the release workflow built
    26	// (JUSPRIN_PAGE_BUILD, read by vite.config.ts), "local" elsewhere. Sentry
    27	// files the page's source map under it (Packaging/sentry_page_maps.sh), as a
    28	// release's "dist", so builds that share a version keep their own maps.
    29	declare const __JUSPRIN_PAGE_BUILD__: string;
    30	
    31	// The SDK runs only with a DSN. This one names no host that exists, and the
    32	// transport below never sends: every event leaves through beforeSend.
    33	const NOWHERE = 'https://page@jusprin.invalid/0';
    34	
    35	let started = false;
    36	// The page's bridge client, which holds a report until the app can take it.
    37	let deliverTo: (report: PageErrorReport) => void = () => {};
    38	
    39	export function reportOf(event: ErrorEvent, hint: EventHint): PageErrorReport {
    40	  // What the SDK itself does to an event as it sends it, which here it never
    41	  // does: names itself, and drops its own working data.
    42	  event.sdk = { ...event.sdk, name: 'sentry.javascript.browser', version: SDK_VERSION };
    43	  delete event.sdkProcessingMetadata;
    44	  const original = hint.originalException;
    45	  if (original instanceof Error) {
    46	    return { error: `${original.name}: ${original.message}`, where: original.stack ?? '', event };
    47	  }
    48	  const exception = event.exception?.values?.at(-1);
    49	  const error = exception ? `${exception.type ?? 'Error'}: ${exception.value ?? ''}` : String(original);
    50	  return { error, where: '', event };
    51	}
    52	
    53	// Starts catching, once per page, with every integration the SDK has by
    54	// default and the one that names frames below; `deliver`, the latest bridge
    55	// client's, hands each report to the app.
    56	export function startErrorReports(deliver: (report: PageErrorReport) => void): void {
    57	  deliverTo = deliver;
    58	  if (started) return;
    59	  started = true;
    60	  // The page loads from the app's resources folder (Support/PageScheme.hpp):
    61	  // jusprin:///home/index.html on macOS and Linux, and on Windows a file://
    62	  // address wherever the app is installed.
    63	  // Sentry finds the page's source map by a frame's file name
    64	  // (Packaging/sentry_page_maps.sh), so frames name the page's folder the same
    65	  // way on every computer: app:///home/index.html.
    66	  const folder = new URL('.', window.location.href);
    67	  const name = folder.pathname.split('/').filter(Boolean).pop() ?? '';
    68	  init({
    69	    dsn: NOWHERE,
    70	    dist: __JUSPRIN_PAGE_BUILD__,
    71	    integrations: [rewriteFramesIntegration({ root: folder.href, prefix: name ? `app:///${name}/` : 'app:///' })],
    72	    transport: (options) => createTransport(options, () => Promise.resolve({})),
    73	    beforeSend(event, hint) {
    74	      deliverTo(reportOf(event, hint));
    75	      return null;
    76	    },
    77	  });
    78	}
     1	// The source map Sentry needs to name the page's own code in an error's
     2	// stack (Packaging/sentry_page_maps.sh). The page's code runs from a script
     3	// inlined into index.html (vite-plugin-singlefile), so a stack gives lines
     4	// and columns in index.html, not in the script Vite built. This maps those
     5	// positions to the page's source files. The map is written beside the
     6	// build, never into the folder the app ships.
     7	import { mkdirSync, writeFileSync } from 'node:fs';
     8	import { dirname } from 'node:path';
     9	import remapping, { type SourceMapInput } from '@jridgewell/remapping';
    10	import MagicString from 'magic-string';
    11	import type { Plugin } from 'vite';
    12	
    13	// The map from positions in `html` to the sources of `code`, the script
    14	// vite-plugin-singlefile inlined into it with `codeMap` as its map. Makes the
    15	// plugin's edits to the script again (its replaceScript) and fails unless
    16	// they give back the script exactly as `html` holds it.
    17	export function mapInlinedScript(html: string, code: string, codeMap: SourceMapInput, codeFile: string): string {
    18	  const edited = new MagicString(code);
    19	  for (const found of code.matchAll(/"?__VITE_PRELOAD__"?/g)) {
    20	    edited.overwrite(found.index, found.index + found[0].length, 'void 0');
    21	  }
    22	  for (const found of code.matchAll(/<(\/script>|!--)/g)) {
    23	    edited.overwrite(found.index, found.index + 1, '\\x3C');
    24	  }
    25	  edited.trim();
    26	  const inlined = edited.toString();
    27	  const at = html.indexOf(inlined);
    28	  if (at < 0 || html.indexOf(inlined, at + 1) >= 0) {
    29	    throw new Error(`index.html does not hold ${codeFile} exactly once as vite-plugin-singlefile inlines it, so no source map can be made`);
    30	  }
    31	  edited.prepend(html.slice(0, at));
    32	  edited.append(html.slice(at + inlined.length));
    33	  const htmlMap = edited.generateMap({ source: codeFile, file: 'index.html', hires: 'boundary' });
    34	  const map = remapping(htmlMap.toString(), (source) => (source === codeFile ? codeMap : null));
    35	  map.file = 'index.html';
    36	  return map.toString();
    37	}
    38	
    39	// Vite plugins: the first keeps the built script and its map before
    40	// vite-plugin-singlefile inlines it, the second writes the map of the
    41	// finished index.html to `mapFile`. List them after viteSingleFile().
    42	export function inlinedScriptSourceMap(mapFile: string): Plugin[] {
    43	  const scripts = new Map<string, { code: string; map: SourceMapInput }>();
    44	  return [
    45	    {
    46	      name: 'jusprin:keep-script-map',
    47	      apply: 'build',
    48	      config: () => ({ build: { sourcemap: 'hidden' } }),
    49	      generateBundle: {
    50	        order: 'pre',
    51	        handler(_options, bundle) {
    52	          for (const output of Object.values(bundle)) {
    53	            if (output.type !== 'chunk' || output.map == null) continue;
    54	            scripts.set(output.fileName, { code: output.code, map: output.map as SourceMapInput });
    55	            // The script's own map would ship with the page.
    56	            delete bundle[`${output.fileName}.map`];
    57	          }
    58	        },
    59	      },
    60	    },
    61	    {
    62	      name: 'jusprin:inlined-script-map',
    63	      apply: 'build',
    64	      enforce: 'post',
    65	      generateBundle(_options, bundle) {
    66	        const page = bundle['index.html'];
    67	        if (page?.type !== 'asset' || scripts.size !== 1) {
    68	          this.error(`expected one index.html and one script, found ${scripts.size} script(s)`);
    69	        }
    70	        const [[codeFile, script]] = [...scripts];
    71	        const map = mapInlinedScript(String(page.source), script.code, script.map, codeFile);
    72	        mkdirSync(dirname(mapFile), { recursive: true });
    73	        writeFileSync(mapFile, map);
    74	      },
    75	    },
    76	  ];
    77	}
