    35	    const std::string body = launch_report_body(install_id(config), version_label(), std::string(wxGetOsDescription().ToUTF8()));
    36	    Http::post(Agent::cloud_launches_url(&config))
    37	        .header("Content-Type", "application/json")
    38	        .header("User-Agent", user_agent())
    39	        .set_post_body(body)
    40	        .timeout_connect(5)
    41	        .timeout_max(10)
    42	        .on_error([](std::string answer, std::string error, unsigned status) {
    43	            // On the HTTP thread; report_if_automatic goes on to the main thread.
    44	            if (const auto report = launch_failure_report(status, answer))
    45	                report_if_automatic("telling JusPrin's server that the app started", *report);
    46	            else
    47	                BOOST_LOG_TRIVIAL(info) << "JusPrin's start report reached no server: " << error;
    48	        })
    49	        .perform();
