 37	// overflow-wrap: anywhere does: an error names paths with no space to break at.
 38	wxString wrap_anywhere(const wxString& text, const wxFont& font, int width, wxWindow& window)
 39	{
 40	    wxClientDC dc(&window);
 41	    dc.SetFont(font);
 42	    wxString out;
 43	    for (const wxString& paragraph : wxSplit(text, '\n', '\0')) {
 44	        wxString line;
 45	        const auto fits = [&](const wxString& candidate) { return dc.GetTextExtent(candidate).x <= width; };
 46	        for (const wxString& word : wxSplit(paragraph, ' ', '\0')) {
 47	            const wxString joined = line.empty() ? word : line + " " + word;
 48	            if (fits(joined)) {
 49	                line = joined;
 50	                continue;
 51	            }
 52	            if (!line.empty()) {
 53	                out += line + "\n";
 54	                line.clear();
 55	            }
 56	            for (const wxUniChar c : word) {
 57	                if (!line.empty() && !fits(line + c)) {
 58	                    out += line + "\n";
 59	                    line.clear();
 60	                }
 61	                line += c;
 62	            }
 63	        }
 64	        out += line + "\n";
 65	    }
 66	    out.RemoveLast();
 67	    return out;
 68	}
