179	ErrorReportDialog::~ErrorReportDialog()
180	{
181	    if (g_open == this)
182	        g_open = nullptr;
183	}
185	wxPanel* ErrorReportDialog::build_contents(const ErrorReport& report)
186	{
187	    const ShellPalette& palette = m_theme.palette(wxGetApp().dark_mode());
188	    auto* contents = new wxPanel(this);
189	    contents->SetBackgroundColour(palette.surface_raised);
190	    auto* box = new wxPanel(contents);
191	    box->SetBackgroundColour(palette.surface_subtle);
193	    const int value_width = FromDIP(kWidth - 2 * 24 - 2 * 12 - kNameWidth - 8);
194	    auto*     rows        = new wxFlexGridSizer(2, FromDIP(8), FromDIP(8));
195	    rows->AddGrowableCol(1);
196	    const auto add_row = [&](const wxString& name, const wxString& value) {
197	        auto* name_label = new wxStaticText(box, wxID_ANY, name);
198	        style_label(*name_label, m_theme, TextRole::LabelBold, palette.text_secondary);
199	        name_label->SetMinSize(wxSize(FromDIP(kNameWidth), -1));
200	        auto* value_label = new wxStaticText(box, wxID_ANY, wxEmptyString);
201	        value_label->SetFont(m_theme.code_font());
202	        value_label->SetForegroundColour(palette.text_primary);
203	        value_label->SetLabelText(wrap_anywhere(value, m_theme.code_font(), value_width, *value_label));
204	        rows->Add(name_label, 0);
205	        rows->Add(value_label, 1, wxEXPAND);
206	    };
207	    // The report's lines as Sentry receives them, in their own words:
208	    // a report is read by the team, in English.
209	    add_row(_L("App"), wxString::FromUTF8(report.app + " on " + report.os));
210	    add_row(_L("Was doing"), wxString::FromUTF8(report.doing));
211	    add_row(_L("Error"), wxString::FromUTF8(report.error));
212	    int where_lines = 0;
213	    if (!report.where.empty()) {
214	        where_lines = 1 + int(std::count(report.where.begin(), report.where.end(), '\n'));
215	        add_row(_L("Where"),
216	                // TRN %d is how many lines of the stack the report sends, such as 9.
217	                wxString::Format(_L_PLURAL("%d line naming the parts of JusPrin that were running",
218	                                           "%d lines naming the parts of JusPrin that were running", where_lines),
219	                                 where_lines));
220	    }
221	    auto* padded = new wxBoxSizer(wxVERTICAL);
222	    padded->Add(rows, 1, wxEXPAND | wxALL, FromDIP(12));
223	    box->SetSizer(padded);
225	    const wxString note = where_lines == 0 ?
226	        _L("That is the whole report. It has no chat messages, no files, no project names and no account or email address.") :
227	        wxString::Format(
228	            // TRN %d is how many lines of the stack the report sends, such as 9.
229	            _L_PLURAL("That line is not shown in full here. The report has no chat messages, no files, no project names and no "
230	                      "account or email address.",
231	                      "Those %d lines are not shown in full here. The report has no chat messages, no files, no project names "
232	                      "and no account or email address.",
233	                      where_lines),
234	            where_lines);
235	    auto* note_label = new wxStaticText(contents, wxID_ANY, note);
236	    style_label(*note_label, m_theme, TextRole::Label, palette.text_secondary);
237	    note_label->Wrap(FromDIP(kWidth - 2 * 24));
239	    auto* column = new wxBoxSizer(wxVERTICAL);
240	    column->Add(box, 0, wxEXPAND);
241	    column->Add(note_label, 0, wxTOP, FromDIP(8));
242	    contents->SetSizer(column);
243	    return contents;
244	}
246	void ErrorReportDialog::toggle_contents()
247	{
248	    const bool          open    = !m_contents->IsShown();
249	    const ShellPalette& palette = m_theme.palette(wxGetApp().dark_mode());
250	    m_contents->Show(open);
251	    m_chevron->SetBitmap(lucide_bitmap(open ? "chevron-down" : "chevron-right", FromDIP(16), palette.text_secondary));
252	    Layout();
253	    Fit();
254	}
256	void ErrorReportDialog::update_report_label()
257	{
258	    m_report->SetLabel(m_automatic->is_checked() ? _L("Report this and future errors") : _L("Report to JusPrin team"));
259	    m_report->Rescale();
260	    Layout();
261	}
263	} // namespace Slic3r::GUI::JusPrin

